import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecurePathTraversalExample {
    public static void main(String[] args) {
        String userInput = "../etc/passwd"; // Simulated malicious input
        String allowedDirectory = "/safe/uploads/";

        // Construct the path using Paths and resolve against a base directory
        Path basePath = Paths.get(allowedDirectory).toAbsolutePath().normalize();
        Path requestedPath = basePath.resolve(userInput).normalize();

        // Check if the resolved path is still within the allowed base directory
        if (requestedPath.startsWith(basePath)) {
            try {
                Files.readAllBytes(requestedPath);
                System.out.println("File accessed safely.");
            } catch (Exception e) {
                System.out.println("Error reading file.");
            }
        } else {
            System.out.println("Access denied: Path traversal detected.");
        }
    }
}
